fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    if len == 0 {
        return Vec::new(); // Handle empty case, though the problem states the array is non-empty.
    }
    
    // Calculate effective rotation amount
    let rotation_amount = n % len;
    if rotation_amount == 0 {
        return list.clone(); // No rotation needed
    }
    
    // Calculate the split point
    let s = len - rotation_amount;
    
    // Create the new rotated array
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..]); // Add suffix
    new_list.extend_from_slice(&list[0..s]); // Add prefix
    
    new_list
}